def P(t): return "".join(f"<p>{x.strip()}</p>" for x in t.split("||"))
body = []

INTRO=P('A frosty start near freezing gives way to a gray, chilly Tuesday in the upper 40s, ahead of a raw, damp Wednesday and a bright, cold Thanksgiving, with a warm spell to follow over the weekend. At home, the airport cuts the ribbon on its longer runway this morning and early voting opens in the Dec. 1 runoffs; in Little Rock, a federal judge signaled trouble for Pulaski County’s data-center ordinance; and Nvidia brought back Jensen Huang as Wall Street staged a big rebound. The moon is full today.')
ZONE='<table class="mk"><tr><th>Zone</th><th>Archery</th><th>Youth gun</th><th>Modern gun</th><th>Muzzleloader</th></tr><tr><td>3</td><td>Sept. 26, 2026 – Feb. 28, 2027</td><td>Nov. 7-8, 2026; Jan. 2-3, 2027</td><td>Nov. 14 – Dec. 6; Dec. 26-28, 2026</td><td>Oct. 17-25; Dec. 12-14, 2026</td></tr><tr><td>4</td><td>Sept. 26, 2026 – Feb. 28, 2027</td><td>Nov. 7-8, 2026; Jan. 2-3, 2027</td><td>Nov. 14-22; Dec. 26-28, 2026</td><td>Closed</td></tr><tr><td>6</td><td>Sept. 26, 2026 – Feb. 28, 2027</td><td>Nov. 7-8, 2026; Jan. 2-3, 2027</td><td>Nov. 14 – Dec. 6; Dec. 26-28, 2026</td><td>Oct. 17-25; Dec. 12-14, 2026</td></tr><tr><td>8</td><td>Sept. 26, 2026 – Feb. 28, 2027</td><td>Nov. 7-8, 2026; Jan. 2-3, 2027</td><td>Nov. 14 – Dec. 6; Dec. 26-28, 2026</td><td>Oct. 17-25; Dec. 12-14, 2026</td></tr></table>'
body.append('<h1>The Morning Letter</h1><div class="sub">With the compliments of the Editor, to Jonesboro, Brookland &amp; neighbors</div>')
body.append('<div class="date">Tuesday, the Twenty-Fourth of November, 2026</div><div class="orn">&#10086;</div>')
body.append('<p>Good morning,</p>')
body.append(INTRO)
body.append('<h2>The Day Ahead</h2>'); body.append(hourly); body.append(grid)
body.append(P('The morning starts right at the edge of freezing, about 33 degrees at six o’clock under a clear sky, with a north-northeast breeze near 10 miles an hour, so look for frost on windshields and rooftops. A lid of gray cloud slides over by nine, when it is about 38, and stays the rest of the day. The afternoon tops out near 47 to 48 around three o’clock, with the wind picking up to about 14 miles an hour out of the north-northeast, which will make it feel colder than the thermometer says. It stays dry, and the evening settles to about 40 by six and 38 by nine under the clouds.||Wednesday, the big travel day, turns raw and gray: about 37 in the morning and no warmer than the upper 30s in the afternoon, with a 21 percent chance of a little precipitation in the morning rising to about 42 percent by midafternoon; amounts look light, and it will be cold enough that a few wet flakes mixed in would not be a surprise. Thanksgiving Day clears out from a frosty start near 32 to a sunny, breezy afternoon in the mid-40s. Then the warm-up begins: the mid-50s Friday, low 60s Saturday, upper 60s Sunday and near 72 next Monday, mostly dry throughout.'))
body.append('<h2>The Almanac</h2>')
body.append(f'''<table class="alm"><tr><td>First light</td><td>{alm['first_light']}</td><td>Sunrise</td><td>{alm['sunrise']}</td></tr>
<tr><td>Solar noon</td><td>{alm['noon']}</td><td>Sunset</td><td>{alm['sunset']}</td></tr>
<tr><td>Last light</td><td>{alm['last_light']}</td><td>Length of day</td><td>{alm['day_length']}</td></tr>
<tr><td>Change from yesterday</td><td>{alm['change'].replace('-','&minus;')}</td><td>Moon</td><td>{alm['moon']}, {alm['illum']}% lit</td></tr></table>''')
body.append(P('The sun rises at 6:48 and sets at 4:50, for ten hours and two minutes of daylight, about a minute and 21 seconds less than Monday’s. The moon is full today, the November full moon that the old almanacs call the Beaver Moon, after the season when trappers set their lines before the ponds froze. Tonight’s clouds will likely hide it, but Thursday’s clearer sky should show a moon still nearly round, rising in the early evening over the stubble fields.'))
body.append(P('<i>In field and garden:</i> the oaks along Crowley’s Ridge are holding on to their brown leaves, as many young oaks do all winter, rattling in the north wind long after the maples and sweetgums have gone bare. Watch the feeders this week for dark-eyed juncos, the small gray “snowbirds” with white outer tail feathers that come down from the north for the winter and hop about under the bird feeders picking up dropped seed. In the kitchen, a frozen turkey thawing in the refrigerator needs about a day for every four to five pounds, so a big bird still in the freezer this morning will not be ready by Thursday that way; the safe shortcut is to keep it in its wrapper submerged in cold tap water, changed every half hour, allowing about 30 minutes a pound.'))
body.append('<p><i>Weather lore, not a forecast:</i> an old country saying runs, “Clear moon, frost soon.” Tonight’s full moon will be veiled in cloud and the low near 35, so the saying gets no test; but Wednesday night clears, and Thanksgiving morning is forecast near 32.</p>')

body.append('<h2>Of Local Interest</h2>')
body.append(P('Two days before Thanksgiving, the news at home runs to a longer runway, the first ballots in the December runoffs and a good many hot meals.'))
body.append('<h3>A longer runway opens at the Jonesboro airport</h3>')
body.append(P('Jonesboro Municipal Airport, the city’s airfield on Lindbergh Drive, holds a ribbon-cutting at 10:30 this morning to mark the end of work that strengthened its main runway and added 500 feet to it, along with its parallel taxiway. The runway now runs 6,700 feet instead of 6,200, and officials say the extra length will help the airport meet present and future demand; it was designed with faster aircraft such as business jets in mind.||The expansion began in 2017 and was carried out in phases as money for each piece was found. The main runway closed for construction in July, and the airport kept operating on its secondary runway in the meantime. Airport manager George Jackson invited the public to the ceremony, which will be held at FBO Building No. 1, 3901 Lindbergh Drive. (FBO stands for fixed-base operator, the hangar-and-fuel business that serves private pilots.)'))
body.append('<h3>Early voting opens today in the Dec. 1 runoffs</h3>')
body.append(P('Early voting begins this morning in the runoff elections that follow this month’s general election, for races in which no candidate won a majority on Nov. 3. In Craighead County there are two: the Jonesboro City Council seat for Ward 5, Position 1, where incumbent L.J. Bryant faces Patti Lack, and the race for mayor of Lake City, between Daniel Haynes and Jackie Davis Jr.||Craighead County voters may cast early ballots from 8 a.m. to 5 p.m. today, Wednesday, Friday and next Monday, Nov. 30, at the Election Annex in Jonesboro or the Eastern Annex in Lake City; there is no early voting on Thanksgiving Day. Election Day is Tuesday, Dec. 1.||Runoffs are also on the ballot elsewhere in the region: for mayor in Pocahontas (Keith Futrell and Danny Swann), Wynne (Jennifer Hobbs and De’Andra L. Warren), Tuckerman (Roger Williams and Mark Warren), Gosnell (Richard Brown and Jason M. Taylor) and Cherry Valley (Brett Stephens and Christy Phillips), and for two Parkin City Council seats.'))
body.append('<h3>Finance committee to take up license rules and street paving</h3>')
body.append(P('The Jonesboro City Council’s Finance and Administration Committee, the group of council members that reviews money and administrative matters before they go to the full council, meets at 4 p.m. today at the Municipal Center, 300 S. Church St. Its agenda, posted last week, is short.||The main item is a proposed ordinance that would add sections to the city code setting out standard guidance and what the city expects of businesses holding a city privilege license (the yearly license businesses need to operate in Jonesboro). The committee will also consider accepting the low bid from Atlas Asphalt, Inc. for milling and resurfacing selected city streets, work paid for with a Community Development Block Grant, the federal money cities receive to improve lower-income neighborhoods; the agenda does not list the bid amount or the streets. Five resolutions would place $275 municipal liens, claims the city files against a property to recover what it spent cleaning up or mowing it, on properties around town.||Items the committee approves go on to the full City Council. The committee’s next meeting is Tuesday, Dec. 8.'))
body.append('<h3>Hot meals, and hands to serve them, for Thanksgiving</h3>')
body.append(P('The 30th Jonesboro Community Thanksgiving, the free holiday dinner held each year at St. Bernards Auditorium on East Washington Avenue, opens at 10 a.m. Thursday and serves until the food runs out. Organizer Barbara Sanders said the effort turns out about 2,500 meals a year, close to 2,000 of them delivered to homes and 200 to 300 eaten on site. Volunteers can sign up online through today, and the group says it can still use help.||The Salvation Army in Jonesboro will hold its usual 5 p.m. dinner on Thanksgiving Day; office coordinator Holly McLeod said volunteers are needed there too, and can call 870-932-3785.||North of town, the Bono Senior Citizen Center on College Street will serve its sixth annual free Thanksgiving meal from noon to 1:30 p.m. Thursday: turkey, dressing, giblet gravy, mashed potatoes, green beans, corn and dessert. It is open to everyone, first come, first served, with no sign-up or ID needed. The center served about 75 meals last year and is planning for more than 100. It also delivers in Cash and Egypt; delivery requests must be in by today, with volunteer Gayle Pennington at 870-761-4436.'))
body.append('<h3>Red Wolves athletes box up Thanksgiving dinners</h3>')
body.append(P('Athletes from across Arkansas State University’s teams spent the week before Thanksgiving on a volunteer project they called One Pack Gives Back, run by the university’s Student Athlete Advisory Committee, the group that represents athletes’ views to the athletic department. Working with Volunteer A-State and its campus food pantry, they shopped for groceries at Bill’s Cost Plus Supermarket on Wednesday, assembled boxed meals on Thursday and Friday, and handed them out to selected families at the A-State Food Pantry on Saturday.||Jaelynn Blackwell, a track and field athlete who came to Jonesboro from Maryland, about 15 hours away, said the work helped her settle into Arkansas; teammate Alexis Waller, a triple jumper, said it helped her get to know athletes in other sports. Both are recruiting more athletes to the committee, and Blackwell urged everyone, not only athletes, to take up community service and to know about the campus food pantry.'))
body.append('<h3>From the courthouse</h3>')
body.append(P('A Senatobia, Miss., man is being held on $150,000 bond on a charge of internet stalking of a child, a Class Y felony, the most serious class of felony in Arkansas. According to a probable cause affidavit, Donald Graham communicated online with a profile whose user said she was a 14-year-old girl, booked a Jonesboro hotel room and drove to Jonesboro on Saturday, Nov. 21, to pick her up; officers of the Jonesboro Police Department’s Internet Crimes Against Children unit arrested him when he arrived in the 2000 block of West Washington Avenue. The affidavit does not say whether the profile was run by an investigator. Judge Tommy Fowler found probable cause on Monday, and Graham is due in Craighead County Circuit Court on Jan. 25. The charge is an allegation and he has not been convicted.||Miguel Trevino, of Craighead County, is charged with second-degree sexual assault, a Class B felony punishable by 5 to 20 years in prison, after a woman told investigators he touched her without consent while she was driving back to Jonesboro on Nov. 7, after the two had arranged to meet through Facebook Messenger. A judge set bond at $75,000 with a no-contact order, and his next court date is Feb. 25. He has not been convicted.||A trial date has been set for Hunter Joseph Summers, an Arkansas State wide receiver charged with misdemeanor third-degree domestic battering after a woman told university police he assaulted her at the Northpark Quads on campus on Oct. 21. He has pleaded not guilty, and his trial is set for 9 a.m. Feb. 3 in state district court in Jonesboro. He remains on the team’s roster; the athletic department said it was gathering information and declined further comment.'))
body.append('<h3>In brief</h3>')
body.append(P('<b>The whole holiday trash schedule.</b> Jonesboro’s sanitation and recycling crews will not run Thursday or Friday, and pickups shift through the following week: next Monday, Nov. 30, the Thursday trash routes; Tuesday, Dec. 1, the Friday routes; Wednesday, Dec. 2, both the Monday and Tuesday routes; Thursday, Dec. 3, the Wednesday routes; Friday, Dec. 4, the Thursday routes; and Saturday, Dec. 5, the Friday routes. Regular trash days return Monday, Dec. 7. Recycling runs the fourth-Tuesday route today and the fourth-Wednesday route tomorrow; the fourth-Thursday and fourth-Friday routes move to Nov. 30 and Dec. 1, the first-Tuesday and first-Wednesday routes are both picked up Dec. 2, and the first-Thursday and first-Friday routes run Dec. 3 and 4.'))
body.append('<h3>Around town</h3>')
body.append(P('<b>Today, Tuesday, Nov. 24.</b> Runway ribbon-cutting at Jonesboro Municipal Airport, FBO Building No. 1, 3901 Lindbergh Drive, 10:30 a.m. (public welcome). Runoff early voting, 8 a.m. to 5 p.m., Election Annex in Jonesboro and Eastern Annex in Lake City. City Council Finance and Administration Committee, 4 p.m., Municipal Center, 300 S. Church St. Last day to sign up to volunteer for the Community Thanksgiving meal and to request a Bono Senior Center meal delivery to Cash or Egypt (870-761-4436). Santa’s North Pole is open at 4502 Access Road through Christmas Eve ($8; hours vary).||<b>Wednesday, Nov. 25.</b> Runoff early voting, 8 a.m. to 5 p.m., both annexes.||<b>Thanksgiving Day, Thursday, Nov. 26.</b> DAV Chapter 26 Turkey Trot 5K, 7 a.m. (registration at 6), from the military science building at 1921 Aggie Road ($40). Gearhead Outfitters’ Thanksgiving Turkey Trot, 9 a.m., Craighead Forest Park, walk or run on trail or pavement (free; bring canned and boxed food, diapers, wipes or baby formula for the Food Bank of Northeast Arkansas). Jonesboro Community Thanksgiving Meal, from 10 a.m. until the food runs out, St. Bernards Auditorium, 505 E. Washington Ave. (free). Bono Senior Citizen Center Thanksgiving meal, noon to 1:30 p.m., College Street, Bono (free, open to all). Salvation Army Thanksgiving dinner, 5 p.m. (free). Christmas at the Park, the drive-through lights at Joe Mack Campbell Park, 600 Harry Drive, opens and runs nightly through Dec. 24.||<b>Friday, Nov. 27, and Monday, Nov. 30.</b> Runoff early voting, 8 a.m. to 5 p.m.||<b>Looking ahead.</b> Runoff Election Day, Tuesday, Dec. 1; Jonesboro Christmas Parade on Main Street, Friday, Dec. 4, 7 p.m.; Brookland Christmas Parade, Sunday, Dec. 6, 2 p.m., lining up at Brookland High School.'))
body.append('<h3>Our Neighbors Farther Afield</h3>')
body.append(P('<b>Hardy and Lawrence County.</b> U.S. Sen. John Boozman, Arkansas’s senior senator and the author of a new farm bill he calls Farm Bill 2.0, made stops around Northeast Arkansas. In Hardy, in Sharp County, he visited the city’s wastewater treatment plant, for which he secured more than $1 million in federal money this year, and said aging water systems are a problem nationwide. He also toured the Shirey Bay Rainey Brake Wildlife Management Area with Game and Fish Commission officials and looked at levee improvements in the Lake Charles area, paid for with $11.8 million in federal money he obtained in 2024; Ben Batten, the commission’s deputy director, said the work will improve water flow and help future duck seasons. Boozman, who said residents told him most about the cost of living, gasoline and health care, planned a stop at Arkansas State University-Newport today, and said he hopes to pass the farm bill before this session of Congress ends, though disagreements over food-stamp (SNAP) provisions stand in the way. He said he has not decided whether to run again in 2028.||<b>McDougal.</b> A Marmaduke man, Jeffery Byron Holman, 41, is accused of attacking an off-duty Clay County sheriff’s deputy and a McDougal constable and trying to take the deputy’s gun on Saturday morning, Nov. 21. Clay County Sheriff Ronnie Cole said the officers had followed a pickup driving erratically on U.S. 62 to the old gin lot in McDougal; the driver then fled west, onto county roads, and stopped on a field road near Highway 141, where the struggle took place. The deputy was treated for cuts. Holman was booked into the Clay County jail on two counts of aggravated assault, fleeing, reckless driving, littering and an open-container charge; the charges are allegations.'))
body.append('<div><h2>From the Police Reports</h2><p class="note">Jonesboro Police incident reports. Charges are allegations. No names are printed.</p><p>The department posted 86 incident reports covering Friday morning, Nov. 20, through early Monday, Nov. 23; 43 of them ended in an arrest or citation.</p><p><i>Friday.</i> Someone shot an arrow through a living-room window on Lafayette Lane in the afternoon (criminal mischief). Two fraud reports came in: a woman said about $1,200 was moved out of her bank account without her permission, Links Circle area (felony financial identity fraud and theft), and another said her card number was used at the Walmart on East Highland Drive. A driver stopped for running a stop sign near North Church Street was arrested on suspended-license and obstruction charges.</p><p><i>Overnight into Saturday.</i> At about 1:45 a.m., someone fired into a home in the 72405 area and broke a front window; no injuries were listed. Police filed it as an attempted terroristic act, a felony, and no arrest has been made. A handgun was reported stolen from an apartment on Bekah Drive (felony theft of a firearm). A window was smashed on an SUV on Darlene Drive and items were taken, and $400 in cash was taken from an unlocked car on Trinity Oaks Drive. A man was cited for disorderly conduct after walking through yards and looking in windows on Peachtree Avenue around 6 a.m., and a man was arrested on Stone Street on battery, public-intoxication and warrant charges.</p><p><i>Saturday.</i> A wallet holding about $1,200 in cash, cards and ID was reported stolen on Fair Park Boulevard (felony theft). A woman in the 72404 area said a relative threatened to have her home shot up (terroristic threatening, a felony). An SUV was stolen overnight from Cobb Street, and a car stolen in an earlier case turned up on Arch Street. On Brazos Street a resident found a hole in her kitchen ceiling, possibly from someone getting in through the attic (criminal trespass). Arrests included disorderly conduct at the Walmart on East Highland, public intoxication and marijuana on Parkwood Road, and a driver who refused to give his name at Needham Street and South Caraway Road.</p><p><i>Sunday.</i> A pickup was keyed on Creek Drive, about $1,500 in damage (felony criminal mischief). A man was arrested at a hospital on East Johnson Avenue on felony charges of aggravated assault on a health-care worker and terroristic threatening. Other arrests: shoplifting, marijuana and resisting arrest at the Walmart on East Highland; public intoxication on Southwest Drive; marijuana, evidence tampering and obstruction on School Street; and resisting arrest and fleeing on foot after a disturbance call in Bay. A hit-and-run was reported at East Highland Drive and South Main Street. Just after midnight Monday, a pickup hit a sign at the dead end of Auction Road, and officers logged a large quantity of silver bars from the truck as found property.</p><p><i>Impaired driving.</i> Eight people were arrested on DWI charges over the weekend. In a two-pickup crash at Cate Avenue and South Bridge Street early Sunday, one truck ended up on its side and firefighters freed three people inside; a driver was charged with DWI, refusing a chemical test and running a stop sign. Other DWI arrests followed crashes at East Highland Drive and South Caraway Road on Saturday, at Bradley and North Culberhouse streets and at Johnson Avenue and Main Street on Sunday, and a carport strike near Broadmoor and Brooke Circle; the rest came from stops near Flint Street and West Huntington Avenue, East Matthews Avenue and South Church Street, and Allen and Drake streets.</p><p><i>Domestic cases.</i> Nine reports of domestic battery or assault on a family or household member: seven in the 72401 area, one in 72404 and one in 72405. Six led to arrests, including a felony repeat-offense domestic battery charge and charges of interfering with an emergency call and violating a no-contact order (all 72401 area).</p><p><i>Juvenile and other cases.</i> Marijuana possession at school, juvenile arrested, 72401 area. Theft of a firearm, juvenile suspect, 72404 area. Fleeing, juvenile arrested, 72401 area. Domestic battery and terroristic threatening, juvenile arrested, 72401 area. A fight with battery charges, juvenile among the suspects, 72401 area. An endangering-the-welfare-of-a-minor report, 72401 area. Two reports with juvenile victims and two sexual-offense reports, one with an arrest, are not detailed. The rest were mostly 11 warrant arrests for unpaid fines or missed court dates, suspended-license and marijuana stops, and lost-and-found property.</p><p><b>Safety tip:</b> Eight DWI arrests in one weekend, several after crashes, and Thanksgiving travel starts now: settle on a sober driver or a ride home before the gathering starts.</p>')
body.append('<p class="note" style="break-after:avoid;margin-bottom:2pt">At the county jails</p><p>The Craighead County jail roster listed 311 people held early Tuesday, with 25 booked in the last 48 hours. Among the newest bookings listed first, drug charges were most common (marijuana possession, one count with intent to deliver, and meth or cocaine possession), along with holds for other agencies and unpaid fines, a failure to appear, a parole violation, a domestic-assault charge and a felony theft-from-a-building charge. In Pocahontas, the Randolph County Sheriff’s Office listed 64 people held, with three bookings in the last 48 hours, on public-intoxication and theft, felony commercial-burglary and court-hold charges, and two people released.</p></div>')
body.append('<h2>From the State</h2>')
body.append('<h3>Data center judge sees likely open-meetings violation</h3>')
body.append(P('U.S. District Judge Lee Rudofsky said Monday that he was “concerned significantly” that a Pulaski County justice of the peace broke the state’s open-meetings law while pushing the county’s new data-center ordinance, a finding that would make the ordinance invalid. He spoke at the end of a daylong hearing in Little Rock on AVAIO Digital’s request for a preliminary injunction, a court order that would keep the county from enforcing the ordinance against its planned $6 billion data center near Wrightsville while the company’s lawsuit goes forward. The Quorum Court, the county’s elected governing board, passed the ordinance in October over the veto of County Judge Barry Hyde; it requires a Planning Board permit for “high-intensity digital infrastructure.”||The dispute centers on Justice of the Peace Julie Blackwood, who is a defendant along with the county and Judge Hyde. AVAIO says she called fellow members before the Aug. 25 meeting to line up votes, which would amount to an illegal private meeting; she testified that she asked only whether they would attend. The judge said her text messages pointed the other way and told her lawyer, John Adams, “It looks pretty bad for your client,” though he noted the Quorum Court could likely pass a similar ordinance again quickly. Company witnesses testified that the site plan approved in August was all the county permission the project needs, and County Judge-elect Wendell Griffen, who campaigned against data centers and takes office Jan. 1, testified that he drafted the ordinance himself, using artificial-intelligence tools to understand some concepts.||Friday’s proposed settlement between AVAIO and Judge Hyde, which the court refused to sign, is off the table, and the full lawsuit is months from trial. Judge Rudofsky said he would try to rule on the injunction soon; reports differ on whether he set this Friday or Dec. 4 as his goal.'))
body.append('<h3>Senator files bill to replace Arkansas’ Medicaid expansion</h3>')
body.append(P('State Sen. Bryan King, a Green Forest Republican, has filed the first bill of the coming session that proposes a specific replacement for ARHOME, Arkansas’ version of Medicaid expansion, which uses federal and state Medicaid money to buy private insurance for about 209,000 low-income adults. Senate Bill 9 would direct Gov. Sarah Huckabee Sanders to seek federal permission to move those enrollees into traditional “fee-for-service” Medicaid, in which the state pays doctors and hospitals directly, starting Jan. 1, 2028, and would repeal ARHOME at the end of 2027.||The program, first known as the “private option,” has run under a federal waiver since 2014, but the Trump administration refused to renew it for five years and granted only a six-month extension; Centene Corp. is also leaving, which would leave Arkansas Blue Cross and Blue Shield as the only insurer. A state-hired actuary found in July that ARHOME costs almost twice as much as traditional Medicaid. Sen. King says the savings could help clear the waiting list of nearly 2,500 Arkansans with disabilities seeking home- and community-based services.||Bo Ryall, president of the Arkansas Hospital Association, warned that hospitals could lose hundreds of millions of dollars under a new model even if paid at Medicare rates. Sen. Joshua Bryant of Rogers, recently elected Senate president pro tempore, said more bills are likely and urged colleagues not to pick sides yet. The Legislature convenes Jan. 11.'))
body.append('<h3>Democrats file bills to raise the minimum wage to $15</h3>')
body.append(P('Four Democratic lawmakers from East and central Arkansas have filed three bills to raise the state’s minimum wage, now $11 an hour, where voters set it in 2018. Rep. Lincoln Barnett, a former mayor of Hughes who represents parts of Crittenden and St. Francis counties, filed them with Rep.-elect Audrey Willis of Marion and Sens.-elect Jessie McGruder of Marion and Tara Shephard of Little Rock.||House Bill 1008 would raise the wage to $15 on Jan. 1, 2028; House Bill 1009 would raise it to $13.50 as soon as it takes effect and to $15 a year later. House Bill 1010 would leave the rate alone but end exemptions that let employers with fewer than four workers, and those hiring full-time students, apprentices or workers with disabilities, pay less than the minimum.||The bills come after Gov. Sanders recently told viewers of ABC’s “The View” that Arkansas’ minimum wage is $15, and alongside a separate proposed ballot measure, submitted to Attorney General Tim Griffin’s office this month, that would raise the wage $1 a year. None has had a hearing; the session opens Jan. 11.'))
body.append('<h3>“Jacksyn Act” would raise the age to buy fireworks</h3>')
body.append(P('The same East Arkansas lawmakers, Rep. Lincoln Barnett and Sen.-elect Jessie McGruder, have filed two bills named for Jacksyn Smith, a 14-year-old from Hughes in St. Francis County who died after a firework exploded on July 4; his grandmother has said he was holding one that was “designed to be placed on the ground.” Arkansas now lets children as young as 12 buy fireworks.||House Bill 1006 would raise the buying age to 18 and require adult supervision for anyone under 18 setting them off. House Bill 1007, a middle course, would set the age at 16, require 16- and 17-year-olds to shop with an adult at least 21, and require supervision for anyone under 16. Both await the session that begins Jan. 11.'))
body.append('<h3>Oaklawn opens its racing season Friday</h3>')
body.append(P('Live thoroughbred racing returns Friday to Oaklawn in Hot Springs, the state’s historic track, starting a season that runs into the spring and builds toward the $1.5 million Arkansas Derby on April 10, a major stepping-stone to the Kentucky Derby. The first two weekends race Friday and Saturday only; from Dec. 11, most weekends run Friday through Sunday.||Gates open at 11 a.m. Friday, with first post at 12:30 p.m.; general admission is free and parking in Oaklawn’s lots is $5 cash. Other big days include the Smarty Jones Stakes on Jan. 2, the Rebel Stakes on March 13 and the Apple Blossom and Oaklawn Handicap, each $1.5 million, on April 17.'))
body.append('<h3>In brief</h3>')
body.append(P('<b>Little Rock officer charged.</b> Little Rock police officer Jadan Mobley-Duckworth, 25, was relieved of duty Monday after being charged with misdemeanor third-degree stalking and booked into the Pulaski County jail; police have not described the conduct behind the charge, which is an allegation. || <b>Explosives in a car.</b> State troopers arrested Keith Cassady, 30, of Harrison during a traffic stop there Friday after finding two taped devices with wires hidden in the car’s overhead console; the Bentonville Police bomb squad determined they were explosives. He faces charges including criminal possession of explosives and evidence tampering. || <b>Capital murder charge.</b> Henry Nugene Dumas II of Little Rock, a parolee, pleaded not guilty Monday to capital murder in Saturday’s shooting death of Tevin Deondrez Hadley, 32, at the Fred W. Parris Towers public housing complex downtown and is being held without bail. || <b>Central Arkansas runoffs.</b> Early voting begins today for Dec. 1 runoffs for Jacksonville mayor (incumbent Jeff Elmore and James Bolden III) and city council seats in North Little Rock and Alexander; sites are closed Thanksgiving. || <b>Lab science scholarships.</b> The University of Arkansas for Medical Sciences received a $3.25 million, five-year federal grant to fund several dozen scholarships a year in medical laboratory science, a field with a shortage of workers, especially in rural areas.'))
body.append('<h2>From the Nation</h2>')
body.append('<h3>Nvidia rehires Jensen Huang as chief executive after Trump steps in</h3>')
body.append(P('Nvidia, the California company that makes most of the chips that power artificial intelligence, reinstated co-founder Jensen Huang as president and chief executive on Monday, 11 days after he resigned and less than a week after the board said it did not intend to bring him back. Mr. Huang stepped down Nov. 12 after admitting extramarital affairs, including one with Alice Huang, a former executive of Megaspeed, a Singapore company; the Justice Department is examining whether she worked for Chinese intelligence and has reached no conclusion, and no one has been charged. The two are not related. Colette Kress, the finance chief who served as interim CEO, returns to her old job; the board’s chairman, Harvey Jones, said Mr. Huang “is the right person to lead NVIDIA,” and Mr. Huang said he would be “a better CEO the second time around.”||President Trump said in a phone interview with CNBC that he spoke to the board “directly and indirectly” and “convinced them,” adding, “I made the deal.” The board said only that it had “received input from senior levels of the United States government” and was confident the move “poses no national security risk.” CNBC, citing three people familiar with the board’s thinking, reported that a personal assurance from Mr. Trump that Mr. Huang had not broken national-security laws sealed the decision, along with the steep fall in the stock after he left. The shares jumped about a third on the news. The same day, the Commerce Department added Megaspeed and six related companies to its trade blacklist on suspicion of diverting Nvidia chips to China; Megaspeed says it acted lawfully.||Senate Democratic Leader Chuck Schumer of New York said Democrats would “wield their full power to investigate any wrongdoing by the Trump Administration” once they control Congress in January, and Sen. Ruben Gallego, an Arizona Democrat, accused the president of “selling out our national security to keep the stock market high.” Rep. Don Bacon, a retiring Nebraska Republican, said the company should have ignored the administration. Mr. Huang is still scheduled to be interviewed by three House committees next week.'))
body.append('<h3>Court clears the Army to detonate Iowa explosives Wednesday</h3>')
body.append(P('The 8th U.S. Circuit Court of Appeals in St. Louis on Monday lifted its pause on the Army’s plan to blow up about 9,500 pounds of degraded lead azide, a highly sensitive explosive used in detonators, at the Iowa Army Ammunition Plant near Middletown, in southeastern Iowa. The court turned down two environmental groups, the Iowa Environmental Council and the Sierra Club, finding that “a controlled detonation with attendant safety measures better alleviates the risk of irreparable harm than the risk of an uncontrolled explosion”; the Army says the material, in 68 barrels found in March, has crystallized and could go off on its own in cold weather. The judges said the Environmental Protection Agency’s emergency permit included adequate safeguards against spreading lead dust, such as sand barriers around the bunker, weather limits and air monitoring.||Earlier Monday, before the ruling, President Trump wrote that he had ordered the Army to hold off until the court agreed and made it “fully subject” to the agreement of Iowa’s governor-elect, Democrat Rob Sand, whom he said he would hold responsible for any “death or destruction” if it did not go ahead. Mr. Sand, who takes office in January, said the decision rests with the federal officials running the job and asked that residents get the same briefing he received. Monday night the acting Army secretary, Adam Telle, said the “carefully controlled detonation” will happen Wednesday morning, based on forecast winds, and called it a “consensus decision” that Mr. Sand ultimately accepted. Lead is a nerve poison, and nearby residents have been told to stay indoors with windows shut during the blast.'))
body.append('<h3>Appeals court reopens Trump’s bid to erase his New York conviction</h3>')
body.append(P('A three-judge panel of the 2nd U.S. Circuit Court of Appeals in New York on Monday revived President Trump’s effort to move his hush-money criminal case from state court to federal court, where he could ask to have the conviction thrown out on grounds of presidential immunity. A Manhattan jury convicted Mr. Trump in 2024 of 34 felony counts of falsifying business records to hide a $130,000 payment to the adult-film actress Stormy Daniels; he was given no punishment, and he denies wrongdoing.||The panel said the late U.S. District Judge Alvin Hellerstein, who died last month at 92, “erred in holding that removal is categorically unavailable in a state criminal case” after a conviction. The guilty verdict stands for now. The panel told a lower federal judge to rule promptly on the request and asked that no further proceedings take place in the state courts in the meantime, which puts on hold Mr. Trump’s separate appeal in New York’s Appellate Division, argued Nov. 5. A spokesman for Mr. Trump’s lawyers called the ruling “prompt and correct”; the Manhattan district attorney’s office declined to comment.'))
body.append('<h3>Trump orders prosecutors to seek death for child killers</h3>')
body.append(P('President Trump signed a memorandum at the Justice Department on Monday directing federal prosecutors to seek the death penalty for first-degree murder of a child and for killings committed during a rape, child sexual exploitation, kidnapping or human trafficking, and to carry out existing federal death sentences “as quickly as possible.” “Once juries have spoken, capital punishment will be swift and certain,” he said. It adds to an order he signed on his first day back in office covering, among others, killers of police officers.||The move answers California Gov. Gavin Newsom, a Democrat, who said Nov. 5 that he is changing all 548 death sentences in the state to life without parole; Mr. Trump called that “one of the most shocking acts of injustice our country has ever seen” and said his administration would work to undo it. Mr. Newsom’s office said every one of those inmates will die in prison and accused the president of pardoning wealthy allies. Mr. Trump also asked Congress to pass a bill by Rep. Brandon Gill, a Texas Republican, to write the policy into law, though Democrats will control both chambers in January. Most murder cases are prosecuted by states, so the order reaches only federal cases.'))
body.append('<h3>In brief</h3>')
body.append(P('<b>Thanksgiving travel.</b> Forecasters expect a coastal storm to bring heavy rain and thunderstorms to the Southeast on Wednesday, among the busiest travel days of the year, and rain, wind and possible coastal flooding along the Interstate 95 cities from late Wednesday into Thanksgiving Day, with a little wet snow possible in the mountains of the Northeast; a strong Pacific storm is due to bring heavy rain and mountain snow from Northern California to Washington. Delta Air Lines says it has fixed the computer system that calculates aircraft weight and balance, whose failure Sunday delayed roughly 1,700 to 2,000 flights.'))
body.append('<h2>From Abroad</h2>')
body.append('<h3>Iran vows “all available means” against U.S. blockade as more tankers burn</h3>')
body.append(P('Iran’s Foreign Ministry said Monday it will use “all available means” to break the U.S. Navy’s blockade of Iranian ports, which spokesman Esmaeil Baqaei called an act of military aggression; the United States has blockaded the ports since July to counter Iran’s own closure of the Strait of Hormuz, the narrow passage at the mouth of the Persian Gulf that carries a large share of the world’s oil. Iran’s navy said three oil tankers hit mines in the strait on Monday and two more caught fire after hitting mines east of it on Tuesday, and Britain’s maritime security agency, UKMTO, confirmed an attack Monday on a ship anchored off the United Arab Emirates, with a fire but no reported casualties. The navy said the strait “will never be reopened” until Iran’s demands are met, including lifting the blockade and sanctions and unfreezing its assets.||The U.S. Treasury on Monday sanctioned about two dozen people and companies in Tehran and Dubai it says run Iran’s “shadow banking” network, and Secretary of State Marco Rubio met Qatar’s prime minister, whose government has been carrying messages between the two sides; indirect talks are stalled. President Trump said Sunday that Iran’s drones and missiles had “done no damage” and that he wants a “permanent” deal keeping Iran from a nuclear weapon. U.S. officials are also investigating possible Iranian involvement in cyberattacks on as many as 50 ships carrying oil and other explosive cargo <i>(single source: Wall Street Journal)</i>. In Israel, Gadi Eisenkot, the former army chief trying to form a new government, said he sees no immediate Iranian threat requiring action before then, while caretaker Prime Minister Benjamin Netanyahu warned against downplaying “grave threats.”'))
body.append('<h3>NATO sends a radar plane to Poland after Russian missiles land there</h3>')
body.append(P('NATO will station an AWACS early-warning aircraft, a radar plane that watches the skies and directs allied fighters, over Poland after three Russian Kh-101 cruise missiles came down in the country’s southeast on Friday during a mass Russian strike on Ukraine, Polish Deputy Defense Minister Paweł Zalewski said Monday after an emergency meeting of NATO ambassadors in Brussels. He said every ambassador expressed “full solidarity” with Poland and that the plane will give Poland better “operational awareness” to respond to such threats. Poland, which borders Ukraine, did not invoke Article 4 of the NATO treaty, which calls for formal consultations among allies; its other requests for stronger air defenses on NATO’s eastern edge were put off to a meeting of alliance foreign ministers next week. NATO Secretary-General Mark Rutte has called the incident a “grave violation” of Polish airspace.'))
body.append('<h3>Belgium shut down by strike as budget fight threatens the government</h3>')
body.append(P('Tens of thousands of people marched through Brussels on Monday during a national strike against spending cuts, with police counting about 50,000 and unions about 70,000; all flights at Belgian airports were grounded when air-traffic controllers walked out, and trains, buses and schools were disrupted. The protest is aimed at Prime Minister Bart De Wever, a Flemish nationalist, whose five-party coalition wants to save about 10 billion euros over several years, including cuts in health care and a sales-tax increase, to bring down a deficit above 5 percent of the economy, well over the European Union’s 3 percent limit.||Mr. De Wever offered his resignation Nov. 2 after budget talks broke down, but King Philippe refused it and told him to keep trying. Belgium already missed the EU’s Oct. 15 budget deadline, and Mr. De Wever has warned that his government cannot carry on without a deal; he is due to report to the king again next week.'))
body.append('<h3>Iranian singer flogged 74 times for performing without a head scarf</h3>')
body.append(P('Parastoo Ahmadi, an Iranian singer, and four musicians who performed with her were each given 74 lashes on Monday at the prosecutor’s office in Qom, the country’s religious center, her lawyer, Mostafa Nili, said. They were punished for a December 2024 concert, filmed without an audience at a historic caravanserai and posted on YouTube, in which Ms. Ahmadi sang without a hijab, the head covering Iranian law requires women to wear in public. A Qom court sentenced them for violating public morality, and an appeals court upheld it; the sentence also bars them from performing and from leaving the country for two years. Human-rights groups condemned the flogging, and there was no immediate response from Iranian officials.'))
body.append('<h3>Saudi-led strikes in Yemen kill dozens, Houthis say</h3>')
body.append(P('Yemen’s Houthi rebels, who are backed by Iran and hold the capital, Sanaa, said Monday that an air strike by the Saudi-led coalition on a telecommunications compound in the Red Sea port of Hodeidah killed 17 workers and wounded 11, and that a strike on buses and trucks in Lahj province left 25 people dead or missing. Saudi Arabia did not comment, and the tolls could not be independently confirmed. The coalition, which backs Yemen’s internationally recognized government, said it hit military sites in six provinces, part of a stepped-up campaign since Houthi missiles and drones were fired toward Riyadh, the Saudi capital, in recent days. Hodeidah handles most of Yemen’s commercial imports, and the government says the port remains open.'))
body.append('<h3>In brief</h3>')
body.append(P('<b>Sudan.</b> Drone strikes early Sunday killed at least four people in and around Khartoum, Sudan’s capital, including three members of one family in Omdurman, and hit a United Nations building with staff inside, the U.N. said; Sudan’s army blames drones it says were launched from Ethiopia, which has not been confirmed. The army has been fighting the paramilitary Rapid Support Forces since 2023.||<b>Indonesia.</b> Officials confirmed Tuesday that 26 workers died in Saturday’s fire at a candy factory in Serang, west of Jakarta, and rescuers said most died on the second floor trying to reach the emergency exit; the company’s chief executive said it would help victims’ families.'))
body.append('<h2>Markets &amp; the Farm</h2><p class="note">Figures are as of Monday’s close, November 23, the last trading day. Because Monday was the first day of the week, the week’s change equals the day’s change; the last column instead shows the change over the past five trading days, measured from the close of Monday, November 16.</p><table class="mk"><tr><th>Index</th><th>Close</th><th>Day</th><th>Five days</th></tr><tr><td>S&amp;P 500</td><td class="n">7,237.17</td><td class="n">+326.78 (+4.7%)</td><td class="n">−179.42 (−2.4%)</td></tr><tr><td>Dow Jones Industrials</td><td class="n">49,595.31</td><td class="n">+1,447.98 (+3.0%)</td><td class="n">−2,012.86 (−3.9%)</td></tr><tr><td>Nasdaq Composite</td><td class="n">24,089.56</td><td class="n">+1,471.83 (+6.5%)</td><td class="n">−420.20 (−1.7%)</td></tr></table><p>Stocks staged their biggest one-day rally since April 2025 on Monday, a day after the worst week since then, pulling the S&amp;P 500 back out of correction territory. The spark was Nvidia, the maker of the chips that power most artificial-intelligence systems: its board reinstated co-founder Jensen Huang as chief executive, a week after his departure helped set off the selloff, and the stock jumped 31 percent, lifting chip and other AI-related shares with it. Mergers helped too: the cybersecurity company CrowdStrike agreed to buy its rival Zscaler in an all-stock deal valued at about $44 billion, and the French drugmaker Sanofi agreed to buy the lung-disease drug developer Insmed for about $41 billion in cash. Stock futures pointed about 1 percent lower early Tuesday as chip stocks gave back some of the gains.</p><p>It is a short week: markets are closed Thursday for Thanksgiving and close early, at noon Jonesboro time, on Friday. Today brings a reading on consumer confidence and results from Best Buy, Medtronic, Dell and HP; Wednesday brings October’s PCE inflation index, the Federal Reserve’s preferred price gauge and the last major inflation report before the Fed’s December meeting, along with the second estimate of third-quarter economic growth, weekly jobless claims and results from Deere, the farm-equipment maker.</p>')
body.append('<h3>What analysts are saying</h3>')
body.append('<ul class="picks"><li><b>Analysts leaned toward buying: DG</b> (Dollar General, the Goodlettsville, Tenn., discount chain with thousands of small-town stores, including many across Northeast Arkansas). Piper Sandler raised it to overweight, its buy rating, from neutral on Monday and lifted its price target to $170 from $123, seeing a path to earnings growth in the high teens percent a year for three years on steady same-store sales and improving profit margins. Risk: the call goes against the crowd; about half of the analysts who follow the stock still rate it a hold, and low-income shoppers remain stretched.</li><li><b>Analysts leaned toward buying: TXN</b> (Texas Instruments, the Dallas maker of basic “analog” chips used in cars, factory equipment and household devices). Cantor Fitzgerald raised it to overweight from neutral on Monday after meeting with management, lifting its target to $385 from $340 and calling the share price an attractive entry point; “Overall, we were impressed,” the firm wrote. Risk: chip stocks have swung wildly this month, and demand from industrial and auto customers has been slow to recover.</li><li><b>Analysts leaned toward buying: ZBH</b> (Zimmer Biomet, the Warsaw, Ind., maker of artificial knees, hips and other orthopedic implants). Jefferies raised it to buy from hold on Monday, with a $125 target, up from $120, saying a recent drop in the shares left them cheap compared with other profitable large medical-device makers and offered “a good entry point.” Risk: the call rests mostly on price; the company still has to show faster sales growth.</li><li><b>Analysts turned cautious: DKNG</b> (DraftKings, the online sports-betting and casino-games company). Morgan Stanley cut it to equal weight, a neutral rating, from overweight on Monday and lowered its target to $23 from $31, saying higher marketing costs and the company’s costly push into “prediction markets,” where customers bet on the outcome of events, make its earnings harder to forecast. Risk to the cautious view: if the new business catches on, the shares could recover quickly from their lower price.</li><li><b>Analysts turned cautious: VRT</b> (Vertiv, the Ohio maker of power and cooling equipment for data centers). Baird cut it to neutral from outperform on Monday and slashed its target to $200 from $320, expecting a “buyers’ strike” in the stock until confidence returns in spending on AI data centers, which make up much of its business. Risk to the cautious view: Monday’s sharp AI rebound shows how fast sentiment can turn back in the company’s favor.</li></ul>')
body.append('<p class="note">This is information about what analysts said, not advice to buy or sell.</p>')
body.append('<h3>Commodities</h3>')
body.append('<table class="mk split"><tr><th>Commodity</th><th>Close</th><th>Change</th></tr><tr><td>WTI crude (Jan.), per bbl.</td><td class="n">$80.17</td><td class="n">−$3.24</td></tr><tr><td>Brent crude (Jan.), per bbl.</td><td class="n">$89.37</td><td class="n">−$3.20</td></tr><tr><td>Arkansas avg. regular gas (AAA, Nov. 19)</td><td class="n">$3.37</td><td class="n">−18¢ on week</td></tr><tr><td>Jonesboro metro avg. gas (AAA, Nov. 19)</td><td class="n">$3.35</td><td class="n">−13¢ on week</td></tr><tr><td>Live cattle (Dec.), per cwt</td><td class="n">$224.55</td><td class="n">+$1.55</td></tr><tr><td>Feeder cattle (Jan.), per cwt</td><td class="n">$334.32</td><td class="n">−$1.10</td></tr><tr><td>Lean hogs (Dec.), per cwt</td><td class="n">$52.45</td><td class="n">−15¢</td></tr><tr><td>Corn (Dec.), per bu.</td><td class="n">$4.34¼</td><td class="n">−¼¢</td></tr><tr><td>Soybeans (Jan.), per bu.</td><td class="n">$12.28¾</td><td class="n">+8¢</td></tr><tr><td>Wheat, Chicago (Dec.), per bu.</td><td class="n">$5.77</td><td class="n">+2¾¢</td></tr><tr><td>Rough rice (Jan.), per cwt</td><td class="n">$18.84½</td><td class="n">—</td></tr><tr><td>Cotton (Dec.), per lb.</td><td class="n">77.53¢</td><td class="n">+2.06¢</td></tr></table>')
body.append('<p class="note">These are Monday’s settlements. The December oil contract expired Friday, so crude is now quoted for January delivery; oil fell as President Trump signaled more time for talks with Iran and traders unwound bets on a wider conflict. The gas prices are from AAA’s Nov. 19 release, the latest available. Corn slipped on first-delivery-day selling and a stronger dollar, while soybeans rose on strong export inspections. The rice change is omitted because the reported change did not match the prior close. Rice and cotton: <i>(single source: Brownfield Ag News)</i>.</p>')
body.append('<h2>On the Field</h2>')
body.append(P('<b>Arkansas State men’s basketball</b> (4-2) survived Southern Utah 104-102 on Monday afternoon in Miami, in the opening game of a Thanksgiving-week tournament hosted by Florida International University at the Ocean Bank Convocation Center. Six Red Wolves scored in double figures. Jordan Pyke led with 20 points and 10 rebounds, his second double-double of the season, plus a career-high three blocks; Layne Taylor had 18 points on four 3-pointers, Chaz Watson and Aaron McGee 17 apiece, with four steals for McGee, and Tameron Ferguson handed out eight assists. A-State led 50-41 at the half, but Southern Utah, of the Big Sky Conference, went ahead 90-88 late; Taylor answered with a 3-pointer that started an 11-2 run, the Red Wolves led 99-93 with 34 seconds left, and they made five of six free throws to hold on. They play Long Beach State this afternoon at 2:30 on ESPN+, and the host Panthers on Wednesday afternoon.||<b>Arkansas State football</b> (4-7) ends its season Saturday at 2 p.m. at Centennial Bank Stadium against Troy, which is also 4-7. The Trojans are coming off a 45-7 Senior Day loss to Georgia Southern in which they ran for minus-7 yards. Troy coach Gerad Parker said the Red Wolves have kept their systems in place under interim coach Jalen Ortiz and are “still playing extremely hard for him.” A-State has hired the search firm TurnkeyZRG, paid for with private money, to help find its 32nd head football coach; no hire had been announced as of Monday. ||<b>Arkansas Razorbacks football</b> (4-7, 2-6 SEC) has one week left under first-year coach Ryan Silverfield, who told his players after the 45-3 loss at Texas, “6 days, give me everything you’ve got,” before Saturday’s 11:45 a.m. game against LSU in Fayetteville for the Golden Boot. Another round of roster turnover through the transfer portal is expected to begin next week. LSU (6-5, 3-5 SEC), coached by Lane Kiffin, leads the conference in both total offense, about 470 yards a game, and total defense, but has lost a league-high 19 turnovers and dropped three straight to ranked Alabama, Texas and Tennessee. Five of the last six games in the series have been decided by three points or fewer. ||<b>Tennessee Vols football</b> (9-2, 6-2 SEC) is in a three-way tie with Alabama and Texas for second place in the SEC going into Saturday’s 6 p.m. game at Vanderbilt (4-7, 1-7) on ESPN; Georgia has already clinched one place in the Dec. 5 SEC Championship Game in Atlanta, and the Vols have not played in it since 2007. Coach Josh Heupel said Monday that a conference title remains one of the team’s first goals, though Tennessee does not control the tiebreakers. Running back DeSean Bishop, who has 1,215 rushing yards, was hurt against LSU and is not at full strength, and the Vols lead the nation with 47 sacks. The College Football Playoff committee, which ranked Tennessee ninth last week, releases its new ranking tonight.'))
body.append('<h2>Afield &amp; Afloat</h2>')
body.append('<p class="note">Ratings are rule-of-thumb estimates from the forecast, the rut calendar and the sun, not measurements of animal or fish behavior.</p>')
body.append('<h3>Deer outlook: Excellent</h3>')
body.append(P('Everything that moves deer is in place today: the rut is still in its peak window for north Arkansas, the dawn is near 33, the barometer climbed about a sixth of an inch over the last day behind the weekend’s front, and it begins a slow slide this afternoon as clouds thicken ahead of Wednesday’s weather, which tends to set deer feeding. Best windows: from 6:18 a.m. to about two hours after sunrise, from 10 a.m. to 2 p.m. while bucks are still cruising for does, and from 2:50 p.m. until sunset at 4:50.||<i>Today’s tip:</i> the wind holds out of the north-northeast all day, near 14 miles an hour by afternoon, so sit stands on the south and southwest sides of bedding cover and food plots, where the breeze carries your scent away from the deer, and walk in from the south. A steady wind like this also covers a little noise, a fair day to still-hunt slowly along a ridge into the wind. In Zone 4, around Jonesboro, the gun season is over, so this is a bow day there.'))
body.append(P('<b>Tomorrow, Wednesday (estimate: Good).</b> A raw, gray day with a dawn near 39, a lighter wind near 10 miles an hour, and the barometer down about a seventh of an inch from today; the rut keeps deer on their feet, though the chance of light precipitation rises toward 42 percent by midafternoon. Windows: 6:19 a.m. to about two hours after sunrise, 10 a.m. to 2 p.m., and 2:50 p.m. to sunset at 4:50.||<i>Tomorrow’s tip:</i> make the morning sit count and plan to stay put until midday, before the damp sets in; if it does turn wet late, deer often move right up to dark under a light drizzle, so a short evening sit near a trail into a food source can pay off. Pack a rain shell that does not rustle.'))
body.append('<h3>Fishing outlook: Fair</h3>')
body.append(P('A slowly falling barometer under a gray sky ahead of Wednesday’s weather usually puts fish on a modest feed, and that is about what today offers on Craighead Forest Lake and Lake Frierson, though the cold mornings have been cooling the water steadily and the afternoon only reaches about 47. Best times: late morning through midafternoon, as the water warms a little, and the last hour before sunset at 4:50.||<i>Today’s tip:</i> crappie have been sliding toward deeper brush and drop-offs as the lakes cool, so start around 10 to 15 feet with a small jig or minnow under a slip bobber, fished slowly; bass will hold tight to cover on the wind-blown north and northeast banks. Fish the wind-sheltered side if you are after bream.'))
body.append(P('<b>Tomorrow, Wednesday (estimate: Poor).</b> The barometer drops quickly ahead of the weather, the afternoon stays in the upper 30s and the sky is solid gray, a combination that usually shuts fish down. If you go anyway, the best chance is late morning to early afternoon, before the precipitation chance climbs.||<i>Tomorrow’s tip:</i> slow everything down, a jig dragged along the bottom or a minnow held still over brush, or re-spool reels for the warm weekend ahead.'))

body.append('<h3>In season now, and what is next (zones 3, 4, 6 and 8)</h3>')
body.append(ZONE)
body.append(P('<b>Deer.</b> In Zone 4, home to Craighead County, the rifles are put away until Christmas: bowhunters have the woods through Feb. 28, and the next gun days are the Dec. 26-28 holiday modern gun hunt and the Jan. 2-3 youth weekend. Hunters with land in Zones 3, 6 or 8 still have nearly two weeks of modern gun, through Sunday, Dec. 6, then the Dec. 12-14 Alternative Firearms (muzzleloader) weekend. Zone 4 hunters who took an antlerless deer by gun have used their one; archery allows up to four antlerless deer within the four-deer, two-buck season limit. ||<b>Ducks and geese.</b> The first duck segment has five days left and closes at sunset Sunday, Nov. 29; ducks, coots and mergansers come back Dec. 10-23 and again Dec. 26 through Jan. 31, with the youth, veteran and active-duty military hunt Feb. 6-7. Water is the trouble this year: the Game and Fish Commission has warned that more than a year of drought has left many wetlands dry and is flooding only some of its public units, so check the water-conditions page on agfc.com before driving to a hole. ||<b>Small game.</b> Quail season runs through Feb. 7, and rabbit and squirrel through Feb. 28, good work for a dog and a youngster on the long holiday weekend. '))
body.append('<div style="break-inside:avoid;page-break-inside:avoid"><h2>Postscript</h2>')
body.append('<p class="ps" style="margin-left:2em">Therefore all seasons shall be sweet to thee,<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;. . .<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;whether the eave-drops fall<br>Heard only in the trances of the blast,<br>Or if the secret ministry of frost<br>Shall hang them up in silent icicles,<br>Quietly shining to the quiet Moon.</p>')
body.append('<p class="ps">&mdash; Samuel Taylor Coleridge, “Frost at Midnight” (1798; text as revised in later editions), the closing lines, spoken over his sleeping infant son. On a frosty morning at the edge of freezing, with the full moon hidden behind tonight’s clouds, the poet promises his child that every season, even the coldest, can be sweet.</p>')
body.append('<p class="sign">Until tomorrow, with good wishes &mdash;<br><b>The Editor</b></p>')
body.append('<div class="foot">Compiled from many reports.</div></div>')

# Pastimes
import os, json as _json
fleet = _json.load(open('fleet.json')) if os.path.exists('fleet.json') else None
def fleet_svg(d):
    n=d['size']; cs=30; lab=18; W=lab+n*cs; H=lab+n*cs
    o=[f'<svg viewBox="0 0 {W} {H}" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block;font-family:inherit">']
    for c in range(n): o.append(f'<text x="{lab+c*cs+cs/2}" y="12" text-anchor="middle" font-size="10" fill="#8a6a35">{chr(65+c)}</text>')
    for r in range(n):
        o.append(f'<text x="{lab/2}" y="{lab+r*cs+cs/2+4}" text-anchor="middle" font-size="10" fill="#4a3618">{r+1}</text>')
        for c in range(n):
            x=lab+c*cs;y=lab+r*cs
            o.append(f'<rect x="{x}" y="{y}" width="{cs}" height="{cs}" fill="none" stroke="#8a6a35" stroke-width="1"/><text x="{x+cs/2}" y="{y+cs/2+6}" text-anchor="middle" font-size="17" font-weight="bold" fill="#2b2118">{d["grid"][r][c]}</text>')
    o.append('</svg>'); return ''.join(o)
body.append('<div class="page pastimes"><h2>The Pastimes</h2>')
left='<div><h3>I. Mate in Two</h3>'+f'<div class="board">{past["chess_svg"]}</div>'+f'<p>{past["chess_prompt"]} White is shown with the lighter, outlined pieces; the board is oriented with White at the bottom.</p></div>'
if fleet:
    tot=sum(len(x['word']) for x in fleet['ships'])
    clues=''.join(f'<li><span class="bl">{" ".join("_" for _ in x["word"])}</span> ({len(x["word"])}) {x["hint"]}</li>' for x in fleet['ships'])
    right=('<div><h3>II. Word Fleet</h3>'+'<div style="width:84%">'+fleet_svg(fleet)+'</div>'+
      f'<ol class="clues fl">{clues}</ol>'
      f'<p class="note">Each clue is a definition. Find its word in the grid, across or down. Fire by putting a pencil dot on a letter: one dot is one shot. Check the answers below, then circle each right letter and cross out each wrong one. Your score is your number of dots. <b>Best possible score: {tot} shots.</b> My shots: ________</p></div>')
    sol_ii='II. '+', '.join(f"{x['word']} {chr(65+x['c'])}{x['r']+1} {'across' if x['dir']=='A' else 'down'}" for x in fleet['ships'])
else:
    right='<div><h3>II. The Four Houses</h3>'+f'<p>{past["logic_intro"]}</p><ol class="clues">'+''.join(f'<li>{c}</li>' for c in past['logic_clues'])+f'</ol><p>{past["logic_question"]}</p></div>'
    sol_ii='II. '+past['logic_answer']
body.append('<div class="two">'+left+right+'</div>')
if os.path.exists('comic/today.svg'):
    body.append('<h3 style="margin-top:2pt;margin-bottom:0">III. Sorry, Earth</h3><div class="comic" style="margin:1pt 0 0 0"><img src="comic/today.png" style="width:92%;display:block;margin:0 auto"></div>')
body.append('<div class="flip box"><b>Solutions printed upside down.</b><br>I. '+past['chess_solution']+'<br>'+sol_ii+'</div></div>')

html = f'<!doctype html><html><head><meta charset="utf-8"><title>The Morning Letter</title><style>{css}</style></head><body>'+'\n'.join(body)+'</body></html>'
open('letter.html','w').write(html)
print(len(html))

